{
  "Version": "2012-10-17",
  "Statement": [{
    "Effect": "Allow",
    "Action": ["s3:GetObject"],
    "Resource": "arn:aws:s3:::app-reports/*"
  }]
}
// Attach to a GROUP (ReportReaders); add users to the group.
// EC2/Lambda: attach a ROLE — temporary credentials, auto-rotated.

{
  "Version": "2012-10-17",
  "Statement": [
    {"Effect": "Allow", "Action": "ec2:Describe*", "Resource": "*"},
    {"Effect": "Allow", "Action": ["ec2:StartInstances", "ec2:StopInstances"],
     "Resource": "arn:aws:ec2:us-east-1:123456789012:instance/*",
     "Condition": {"StringEquals": {"ec2:ResourceTag/Env": "dev"}}},
    {"Effect": "Deny", "Action": "ec2:TerminateInstances", "Resource": "*"}
  ]
}

{
  "Effect": "Deny", "Action": "*", "Resource": "*",
  "Condition": {"BoolIfExists": {"aws:MultiFactorAuthPresent": "false"}}
}
// Attach to admins: no MFA, no API calls. Period.
// S3 MFA Delete (versioning must be on):
aws s3api put-bucket-versioning --bucket app-reports \
  --versioning-configuration Status=Enabled,MFADelete=Enabled \
  --mfa "arn:aws:iam::123456789012:mfa/admin 123456"

{
  "Rules": [{
    "ID": "age-out", "Status": "Enabled",
    "Filter": {"Prefix": "logs/"},
    "Transitions": [
      {"Days": 30, "StorageClass": "STANDARD_IA"},
      {"Days": 90, "StorageClass": "GLACIER"}
    ],
    "Expiration": {"Days": 365},
    "NoncurrentVersionExpiration": {"NoncurrentDays": 30}
  }]
}
// Apply: aws s3api put-bucket-lifecycle-configuration
